// Ergebnisse des Information Extractors in Join-Tickets umwandeln.
// Laeuft ueber ALLE Items, weil die Zuordnung ueber die Position erfolgt:
// Der Extractor liefert genau ein Ergebnis je eingehender Mail.
const quellen = $('Mail aufbereiten').all();

function alsJoinDatum(iso) {
  if (!iso) return '';
  const teile = String(iso).trim().split('-');
  if (teile.length !== 3) return '';
  const [jahr, monat, tag] = teile;
  return `${tag}/${monat}/${jahr}`;
}

const ergebnisse = [];
for (let i = 0; i < items.length; i++) {
  const analyse = items[i].json.output ?? items[i].json;
  const quelle = quellen[i] ? quellen[i].json : {};

  // Keine echte Anfrage: kein Ticket. Der Zweig "Kein Ticket noetig"
  // kuemmert sich um diese Mails.
  if (analyse.istEchteAnfrage !== true) continue;

  ergebnisse.push({ json: {
    uid: quelle.uid ?? null,
    absenderMail: quelle.absenderMail,
    betreff: quelle.betreff,
    ticket: {
      id: Date.now() + i,
      title: String(analyse.title || quelle.betreff || 'Anfrage ohne Titel').slice(0, 120),
      description: `${String(analyse.description || '').trim()} Dieses Ticket wurde KI-generiert.`,
      date: alsJoinDatum(analyse.deadline),
      priority: analyse.priority || 'medium',
      category: analyse.category || 'user-story',
      status: 'triage',
      assigned: [],
      subtasks: [],
      creator: {
        email: quelle.absenderMail,
        name: quelle.absenderName || quelle.absenderMail,
        type: 'extern'
      }
    }
  }});
}
return ergebnisse;

// Zweiter Zweig: Mails, die KEINE echte Anfrage waren (Spam, Autoresponder,
// inhaltslose Nachrichten). Sie sind korrekt verarbeitet - bewusst ohne Ticket -
// und gelten deshalb als erledigt.
const quellen = $('Mail aufbereiten').all();
const ergebnisse = [];
for (let i = 0; i < items.length; i++) {
  const analyse = items[i].json.output ?? items[i].json;
  if (analyse.istEchteAnfrage === true) continue;
  const quelle = quellen[i] ? quellen[i].json : {};
  ergebnisse.push({ json: {
    uid: quelle.uid ?? null,
    betreff: quelle.betreff,
    kein_ticket: true,
    grund: 'keine echte Anfrage'
  }});
}
return ergebnisse;

const tls = require('tls');

/**
 * Verschiebt eine E-Mail per IMAP in einen anderen Ordner.
 * Nutzt nur das eingebaute tls-Modul - Dateizugriff ist in dieser
 * n8n-Instanz bewusst gesperrt.
 */
function mailVerschieben(zugang, uid, zielordner, quellordner) {
  return new Promise((resolve, reject) => {
    const socket = tls.connect(
      { host: zugang.host, port: Number(zugang.port) || 993, servername: zugang.host },
      () => {}
    );
    socket.setEncoding('utf8');
    socket.setTimeout(20000);

    let puffer = '';
    let schritt = 0;
    const q = (wert) => `"${String(wert).replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
    const befehle = [
      { tag: 'a1', cmd: `a1 LOGIN ${q(zugang.user)} ${q(zugang.passwort)}` },
      { tag: 'a2', cmd: `a2 SELECT ${q(quellordner)}` },
      { tag: 'a3', cmd: `a3 UID MOVE ${Number(uid)} ${q(zielordner)}` },
      { tag: 'a4', cmd: 'a4 LOGOUT' },
    ];

    const abbrechen = (fehler) => { try { socket.destroy(); } catch (e) {} reject(fehler); };
    socket.on('timeout', () => abbrechen(new Error('IMAP-Zeitueberschreitung')));
    socket.on('error', (e) => abbrechen(e));

    socket.on('data', (teil) => {
      puffer += teil;
      if (schritt === 0) {
        if (!/^\* OK/m.test(puffer)) return;
        puffer = ''; socket.write(befehle[0].cmd + '\r\n'); schritt = 1; return;
      }
      const aktuell = befehle[schritt - 1];
      const antwort = new RegExp(`^${aktuell.tag} (OK|NO|BAD)(.*)$`, 'm').exec(puffer);
      if (!antwort) return;
      if (antwort[1] !== 'OK') {
        return abbrechen(new Error(`IMAP ${aktuell.tag}: ${antwort[1]}${antwort[2]}`));
      }
      // Ein blosses OK beweist nichts: bei unbekannter UID meldet der Server
      // ebenfalls OK. Nur COPYUID/EXPUNGE belegen den echten Umzug.
      if (aktuell.tag === 'a3' && !/COPYUID|EXPUNGE/.test(puffer)) {
        return abbrechen(new Error(`Nachricht UID ${uid} nicht gefunden - nichts verschoben`));
      }
      puffer = '';
      if (schritt >= befehle.length) { socket.end(); return resolve(true); }
      socket.write(befehle[schritt].cmd + '\r\n'); schritt += 1;
    });
  });
}

const zugang = {
  host: $env.JOIN_MAIL_HOST,
  port: $env.JOIN_MAIL_PORT,
  user: $env.JOIN_MAIL_USER,
  passwort: $env.JOIN_MAIL_PASSWORD,
};

// Jedes Item einzeln verschieben. Fehler werden gesammelt statt den ganzen
// Lauf abzubrechen - eine nicht verschiebbare Mail soll nicht das Ticket
// entwerten, das bereits angelegt wurde.
const ergebnisse = [];
for (let i = 0; i < items.length; i++) {
  const uid = ($('Ticket bauen').all()[i] || {}).json?.uid;
  if (!uid) {
    ergebnisse.push({ json: { verschoben: false, grund: 'keine UID ermittelbar' } });
    continue;
  }
  try {
    await mailVerschieben(zugang, uid, 'erledigt', 'INBOX');
    ergebnisse.push({ json: { verschoben: true, uid, ordner: 'erledigt' } });
  } catch (fehler) {
    ergebnisse.push({ json: { verschoben: false, uid, fehler: String(fehler.message) } });
  }
}
return ergebnisse;

